/**
 * Creates the only clock interface consumed by game timelines and schedulers.
 * Changing timeScale preserves continuity, which lets tests accelerate a running flow.
 */
export function createClock({ read = defaultMonotonicNow, initialTimeScale = 1 } = {}) {
  let sourceAnchorMs = read();
  let timelineAnchorMs = sourceAnchorMs;
  let currentTimeScale = requirePositiveScale(initialTimeScale);

  return {
    now() {
      return timelineAnchorMs + (read() - sourceAnchorMs) * currentTimeScale;
    },

    get timeScale() {
      return currentTimeScale;
    },

    set timeScale(nextTimeScale) {
      const sourceNowMs = read();
      timelineAnchorMs += (sourceNowMs - sourceAnchorMs) * currentTimeScale;
      sourceAnchorMs = sourceNowMs;
      currentTimeScale = requirePositiveScale(nextTimeScale);
    },
  };
}

function defaultMonotonicNow() {
  return globalThis.performance?.now?.() ?? Date.now();
}

function requirePositiveScale(value) {
  if (!Number.isFinite(value) || value <= 0) {
    throw new RangeError('timeScale must be a positive finite number');
  }
  return value;
}

export const gameClock = createClock();
import { BASE_POPULATION_CONTROL_VALUES } from '../shared/params.js';
import { gameClock } from '../shared/clock.js';

const SAMPLE_LIMIT = 240;
const SUPPLY_EPSILON = 1e-6;
const clamp = (value, low, high) => Math.max(low, Math.min(high, value));
const finite = (value, fallback) => Number.isFinite(Number(value)) ? Number(value) : fallback;

export function createPopulationControllerState(params) {
  return {
    enabled: false,
    target: BASE_POPULATION_CONTROL_VALUES.populationTarget,
    lastSampleTime: null,
    lastCount: null,
    growthRate: 0,
    commandedGrowthRate: 0,
    logPopulationError: 0,
    lastOatSupplyRate: params.oatSupplyRate,
    saturatedLow: false,
    saturatedHigh: false,
    secondarySeverity: 0,
    baseBurnRate: params.burnRate,
    baseReproThreshold: params.reproThreshold,
    samples: [],
  };
}

export function resetPopulationController(params, state, { preserveBase = false } = {}) {
  if (!preserveBase) {
    state.baseBurnRate = params.burnRate;
    state.baseReproThreshold = params.reproThreshold;
  }
  state.enabled = Boolean(params.usePopulationControl);
  state.target = populationTarget(params);
  state.lastSampleTime = null;
  state.lastCount = null;
  state.growthRate = 0;
  state.commandedGrowthRate = 0;
  state.logPopulationError = 0;
  state.lastOatSupplyRate = params.oatSupplyRate;
  state.saturatedLow = false;
  state.saturatedHigh = false;
  state.secondarySeverity = 0;
  state.samples = [];
  return clonePopulationControllerState(state);
}

